import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { auth } from '../firebase-config';
import { signOut } from 'firebase/auth';
import './Navbar.css'; // Import des styles pour la navbar

const Navbar = () => {
  const navigate = useNavigate();
  const [isAuth, setIsAuth] = React.useState(false);

  React.useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged((user) => {
      setIsAuth(!!user);
    });
    return () => unsubscribe();
  }, []);

  const handleLogout = async () => {
    try {
      await signOut(auth);
      navigate('/login');
    } catch (error) {
      console.error('Erreur lors de la déconnexion:', error);
    }
  };

  return (
    <nav className="navbar">
      <div className="navbar-container">
        <Link className="navbar-logo" to="/">
          💰 Money Management
        </Link>
        <div className="navbar-links">
          <Link to="/"><i className="fas fa-home me-1"></i>Accueil</Link>
          {isAuth ? (
            <>
              <Link to="/profile"><i className="fas fa-user me-1"></i>Profil</Link>
              <button className="btn btn-outline-light ms-2" onClick={handleLogout}>
                <i className="fas fa-sign-out-alt me-1"></i>Déconnexion
              </button>
            </>
          ) : (
            <>
              <Link to="/login"><i className="fas fa-sign-in-alt me-1"></i>Connexion</Link>
              <Link to="/register"><i className="fas fa-user-plus me-1"></i>Inscription</Link>
            </>
          )}
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
